// Video track filtering constraints.
// These constraints are applied to filter out video tracks that don't match the specified criteria.
type TrackFilterConstraintsVideoImpl struct {
	ExcludeFormatsValue []string `json:"exclude_formats,omitempty" validate:"omitempty,dive"`
	FormatsValue        []string `json:"formats,omitempty" validate:"omitempty,dive"`
	MaxWidthValue       *int     `json:"max_width,omitempty" validate:"omitempty,min=1"`
}

// Conditions that must be met for this rule to apply.
// At least one condition must be specified.
// The rule applies if any condition matches (OR logic).
type TrackFilterMatchImpl struct {
	HeadersValue   map[string]string `json:"headers,omitempty" validate:"omitempty"`
	UserAgentValue *string           `json:"user_agent,omitempty" validate:"omitempty"`
}

// A single track filter rule.
// Required: match
type TrackFilterRuleImpl struct {
	MatchValue *TrackFilterMatchImpl            `json:"match" validate:"required"`
	VideoValue *TrackFilterConstraintsVideoImpl `json:"video,omitempty" validate:"omitempty"`
}

