// The list of DVB cards configured on the server.
func (s DvbCardsListImpl) DvbCards() []DvbCardConfig {
	if s.DvbCardsValue == nil {
		return nil
	}
	result := make([]DvbCardConfig, len(s.DvbCardsValue))
	for i, item := range s.DvbCardsValue {
		result[i] = item
	}
	return result
}

// The list of DVB cards configured on the server.
func (s *DvbCardsListImpl) SetDvbCards(v []DvbCardConfig) DvbCardsList {
	if s == nil {
		return nil
	}
	if v != nil {
		impl := make([]*DvbCardConfigImpl, len(v))
		for i, item := range v {
			if itemImpl, ok := item.(*DvbCardConfigImpl); ok {
				impl[i] = itemImpl
			}
		}
		s.DvbCardsValue = impl
	}
	return s
}

