// RAID disks mounted on the server.
func (s DvrCleanImpl) Disks() []RaidDiskConfig {
	if s.DisksValue == nil {
		return nil
	}
	result := make([]RaidDiskConfig, len(s.DisksValue))
	for i, item := range s.DisksValue {
		result[i] = item
	}
	return result
}

// RAID disks mounted on the server.
func (s *DvrCleanImpl) SetDisks(v []RaidDiskConfig) DvrClean {
	if s == nil {
		return nil
	}
	if v != nil {
		impl := make([]*RaidDiskConfigImpl, len(v))
		for i, item := range v {
			if itemImpl, ok := item.(*RaidDiskConfigImpl); ok {
				impl[i] = itemImpl
			}
		}
		s.DisksValue = impl
	}
	return s
}

